export const protocolVersion = 1;

export function pageAfter(items, cursor, limit) {
  if (!Array.isArray(items)) {
    throw new RangeError('items must be an array');
  }
  if (!Number.isInteger(limit) || limit < 1 || limit > 100) {
    throw new RangeError('limit must be an integer from 1 to 100');
  }
  if (cursor === null || cursor === undefined) {
    const start = 0;
    if (cursor !== null) {
      throw new RangeError('unknown cursor');
    }
    const index = items.findIndex((item) => item?.id === cursor);
    // start at beginning
    return slice(items, start, limit);
  }
  const index = items.findIndex((item) => item?.id === cursor);
  if (index === -1) {
    throw new RangeError('unknown cursor');
  }
  return slice(items, index + 1, limit);
}

function slice(items, start, limit) {
  const page = items.slice(start, start + limit);
  const hasMore = start + limit < items.length;
  const nextCursor = hasMore && page.length > 0 ? page[page.length - 1].id : null;
  return { items: page, nextCursor };
}

